import{_ as a,o,c as t,a2 as c}from"./chunks/framework.C0KMm31j.js";const n="/Nav2ArticlesSite/article-assets/2026-07-14/nav2_cover.png",l="/Nav2ArticlesSite/article-assets/2026-07-14/01_launch_orchestration.png",i="/Nav2ArticlesSite/article-assets/2026-07-14/02_sim_bridge.png",r="/Nav2ArticlesSite/article-assets/2026-07-14/03_localization_tf.png",d="/Nav2ArticlesSite/article-assets/2026-07-14/04_costmaps.png",s="/Nav2ArticlesSite/article-assets/2026-07-14/05_planning_bt.png",p="/Nav2ArticlesSite/article-assets/2026-07-14/06_control_loop.png",f=JSON.parse('{"title":"一条 /cmd_vel 是怎样诞生的？从 entry.launch.py 拆解 Nav2 全数据流","description":"myworldbringup/launch/entry.launch.py 看起来只有一百多行，但它不是一个普通的“启动脚本”。它是整个仿真导航系统的装配入口：Ignition Gazebo、ROS 2 bridge、机器人模型、地图与 AMCL、Nav2 行为树、全局规划、TEB 局部控制、速度平","frontmatter":{"title":"一条 `/cmd_vel` 是怎样诞生的？从 `entry.launch.py` 拆解 Nav2 全数据流","description":"myworldbringup/launch/entry.launch.py 看起来只有一百多行，但它不是一个普通的“启动脚本”。它是整个仿真导航系统的装配入口：Ignition Gazebo、ROS 2 bridge、机器人模型、地图与 AMCL、Nav2 行为树、全局规划、TEB 局部控制、速度平","date":"2026-07-14","section":"一 · 架构与启动","readingTime":7,"source":"2026-07-14/myworld_bringup_entry_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-14/nav2_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/myworld-bringup-entry-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一条 `/cmd_vel` 是怎样诞生的？从 `entry.launch.py` 拆解 Nav2 全数据流"}],["meta",{"property":"og:description","content":"myworldbringup/launch/entry.launch.py 看起来只有一百多行，但它不是一个普通的“启动脚本”。它是整个仿真导航系统的装配入口：Ignition Gazebo、ROS 2 bridge、机器人模型、地图与 AMCL、Nav2 行为树、全局规划、TEB 局部控制、速度平"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/myworld-bringup-entry-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-14/nav2_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-14"}],["meta",{"name":"twitter:title","content":"一条 `/cmd_vel` 是怎样诞生的？从 `entry.launch.py` 拆解 Nav2 全数据流"}],["meta",{"name":"twitter:description","content":"myworldbringup/launch/entry.launch.py 看起来只有一百多行，但它不是一个普通的“启动脚本”。它是整个仿真导航系统的装配入口：Ignition Gazebo、ROS 2 bridge、机器人模型、地图与 AMCL、Nav2 行为树、全局规划、TEB 局部控制、速度平"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-14/nav2_cover.png"}]],"prev":{"text":"没有 AMCL，Nav2 怎么跑？拆解 `map→base_link` 自研定位的实车全数据流","link":"/nav2/myagv-entry-full-dataflow"},"next":{"text":"一条导航目标如何指挥整套 Nav2？拆解 `nav2_bt_navigator` 全数据流","link":"/nav2/nav2-bt-navigator-full-dataflow"}},"headers":[],"relativePath":"nav2/myworld-bringup-entry-full-dataflow.md","filePath":"nav2/myworld-bringup-entry-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/myworld-bringup-entry-full-dataflow.md"};function m(_,e,u,g,b,v){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="一条-cmd-vel-是怎样诞生的-从-entry-launch-py-拆解-nav2-全数据流" tabindex="-1">一条 <code>/cmd_vel</code> 是怎样诞生的？从 <code>entry.launch.py</code> 拆解 Nav2 全数据流 <a class="header-anchor" href="#一条-cmd-vel-是怎样诞生的-从-entry-launch-py-拆解-nav2-全数据流" aria-label="Permalink to &quot;一条 `/cmd_vel` 是怎样诞生的？从 `entry.launch.py` 拆解 Nav2 全数据流&quot;">​</a></h1><p><img src="'+n+'" alt="Nav2 全数据流封面"></p><p><code>myworld_bringup/launch/entry.launch.py</code> 看起来只有一百多行，但它不是一个普通的“启动脚本”。它是整个仿真导航系统的装配入口：Ignition Gazebo、ROS 2 bridge、机器人模型、地图与 AMCL、Nav2 行为树、全局规划、TEB 局部控制、速度平滑和 RViz，都从这里被串成一个闭环。</p><p>本文不按文件逐行解释，而是沿着数据真正流动的方向，回答三个问题：数据从哪里来，经过哪些节点，最后如何变成机器人左右轮的运动。</p><h2 id="一、entry-launch-py-到底启动了什么" tabindex="-1">一、entry.launch.py 到底启动了什么 <a class="header-anchor" href="#一、entry-launch-py-到底启动了什么" aria-label="Permalink to &quot;一、entry.launch.py 到底启动了什么&quot;">​</a></h2><p>入口首先解析三个顶层参数：</p><ul><li><code>use_sim_time=true</code>：所有节点使用 <code>/clock</code> 仿真时间。</li><li><code>world_name=myworld2</code>：目前只声明，没有参与 world 文件选择。</li><li><code>use_rviz=true</code>：控制 RViz 是否启动。</li></ul><p>随后它设置 <code>IGN_GAZEBO_RESOURCE_PATH</code>，让 Ignition 能找到系统模型和 <code>myworld_bringup/models</code> 下的资源；设置 <code>IGN_PARTITION=myworld_bringup</code>，隔离当前 Ignition 通信域；最后用 <code>ign gazebo -r -v 3 world_only.sdf</code> 启动仿真。</p><p>入口本身还启动 <code>robot_state_publisher</code>、<code>robot_description_publisher.py</code> 和 RViz，并包含三个子 launch：</p><h3 id="_1-1-ros-ign-bridge-launch-py" tabindex="-1">1.1 <code>ros_ign_bridge.launch.py</code> <a class="header-anchor" href="#_1-1-ros-ign-bridge-launch-py" aria-label="Permalink to &quot;1.1 `ros_ign_bridge.launch.py`&quot;">​</a></h3><p>连接 Ignition Transport 与 ROS 2 topic。</p><h3 id="_1-2-localization-launch-py" tabindex="-1">1.2 <code>localization_launch.py</code> <a class="header-anchor" href="#_1-2-localization-launch-py" aria-label="Permalink to &quot;1.2 `localization_launch.py`&quot;">​</a></h3><p>启动 <code>map_server</code>、AMCL 和定位生命周期管理器。</p><h3 id="_1-3-navigation-launch-py" tabindex="-1">1.3 <code>navigation_launch.py</code> <a class="header-anchor" href="#_1-3-navigation-launch-py" aria-label="Permalink to &quot;1.3 `navigation_launch.py`&quot;">​</a></h3><p>启动 Nav2 导航服务器和导航生命周期管理器。</p><p><img src="'+l+'" alt="entry.launch.py 启动编排"></p><p>这里的关键设计是“入口负责装配，子 launch 负责领域”。仿真、定位、导航分别保持独立，而 <code>params/myworld2.yaml</code> 是定位与导航共享的参数源。</p><h2 id="二、仿真数据如何进入-ros-2" tabindex="-1">二、仿真数据如何进入 ROS 2 <a class="header-anchor" href="#二、仿真数据如何进入-ros-2" aria-label="Permalink to &quot;二、仿真数据如何进入 ROS 2&quot;">​</a></h2><p>Ignition 中的 <code>diffbot</code> 模型包含差速驱动、里程计、关节状态、激光雷达和 IMU 等系统插件。它们产生的是 Ignition Transport 消息，Nav2 不能直接消费，因此需要 <code>ros_gz_bridge/parameter_bridge</code> 做双向类型转换。</p><p><img src="'+i+'" alt="Ignition 与 ROS 2 桥接数据流"></p><p>桥接方向必须看清：</p><ul><li>ROS 2 → Ignition：<code>/cmd_vel</code>，类型从 <code>geometry_msgs/msg/Twist</code> 转为 <code>gz.msgs.Twist</code>。</li><li>Ignition → ROS 2：<code>/clock</code>、<code>/odom</code>、<code>/odom/tf</code>、<code>/joint_states</code>、<code>/scan</code>、<code>/scan/points</code>、<code>/imu</code>、相机图像和相机内参。</li><li><code>/odom/tf</code> 在 bridge 中 remap 为 <code>tf</code>，进入 ROS 2 TF 通道。</li></ul><p>因此 bridge 是整个闭环的“协议边界”：一边是仿真传感器和执行器，另一边是 Nav2 能够理解的标准 ROS 2 消息。</p><h2 id="三、地图、amcl-与-tf-如何组成定位链" tabindex="-1">三、地图、AMCL 与 TF 如何组成定位链 <a class="header-anchor" href="#三、地图、amcl-与-tf-如何组成定位链" aria-label="Permalink to &quot;三、地图、AMCL 与 TF 如何组成定位链&quot;">​</a></h2><p><code>localization_launch.py</code> 使用 <code>RewrittenYaml</code> 把入口传入的地图路径和 <code>use_sim_time</code> 写入临时参数视图，然后启动：</p><ul><li><code>map_server</code>：读取 <code>models/myworld2/myworld2.yaml</code> 及其栅格图，发布 <code>/map</code>。</li><li><code>amcl</code>：消费 <code>/map</code>、<code>/scan</code> 和 TF，估计机器人在地图中的位姿。</li><li><code>lifecycle_manager_localization</code>：按顺序 configure、activate 两个生命周期节点。</li></ul><p><img src="'+r+`" alt="地图、AMCL 与 TF 定位链"></p><p>完整坐标链由三部分拼起来：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AMCL                         Ignition odometry          robot_state_publisher</span></span>
<span class="line"><span>map -&gt; odom                  odom -&gt; base_footprint     base_footprint -&gt; base_link -&gt; base_scan</span></span></code></pre></div><p>最终 Nav2 查询的是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map -&gt; odom -&gt; base_footprint -&gt; base_link -&gt; base_scan</span></span></code></pre></div><p>当前仿真机器人在 <code>world_only.sdf</code> 中以 <code>x=-3.071, y=3.583, yaw=-pi/2</code> 生成，AMCL 参数中的初始姿态也采用相同数值。这两处必须一致，否则仿真真值与定位初值会出现固定偏差。</p><p>需要特别注意：<code>entry.launch.py</code> 向 <code>localization_launch.py</code> 传入的 <code>localization_x/y/z/yaw</code> 等参数，子 launch 当前并未声明或读取。它们不会改变 AMCL 初始姿态，真正生效的是 <code>myworld2.yaml</code> 中的 <code>amcl.initial_pose</code>。</p><h2 id="四、同一份激光如何生成两张代价地图" tabindex="-1">四、同一份激光如何生成两张代价地图 <a class="header-anchor" href="#四、同一份激光如何生成两张代价地图" aria-label="Permalink to &quot;四、同一份激光如何生成两张代价地图&quot;">​</a></h2><p>Nav2 同时维护 global costmap 和 local costmap，但两者目标不同。</p><p><img src="`+d+'" alt="全局与局部代价地图数据流"></p><p>global costmap 工作在 <code>map</code> 坐标系，组合 StaticLayer、ObstacleLayer 和 InflationLayer：静态地图提供长期环境结构，<code>/scan</code> 更新实时障碍，TF 提供机器人位姿。它是全局规划器搜索路径的空间。</p><p>local costmap 工作在 <code>odom</code> 坐标系，是 <code>3 m × 3 m</code> 的 rolling window，更新频率 <code>5 Hz</code>。VoxelLayer 使用 <code>/scan</code> 标记和清除附近障碍，InflationLayer 扩张安全距离。它服务于 controller 和 behavior 的局部碰撞判断。</p><p>两张图都使用 <code>robot_radius=0.28 m</code>。当前 TEB 自身的圆形 footprint 半径为 <code>0.22 m</code>，两者并不一致：TEB 优化阶段可能认为某些间隙可通行，但 costmap 的碰撞检查更保守。调参时应明确这是有意安全裕量，还是需要统一的模型误差。</p><h2 id="五、导航目标如何变成全局路径" tabindex="-1">五、导航目标如何变成全局路径 <a class="header-anchor" href="#五、导航目标如何变成全局路径" aria-label="Permalink to &quot;五、导航目标如何变成全局路径&quot;">​</a></h2><p>RViz 或上层系统发送 <code>NavigateToPose</code> 后，真正接收任务的是 <code>bt_navigator</code>。它加载行为树，在树中调用规划、平滑、控制和恢复 Action。</p><p><img src="'+s+'" alt="导航目标、行为树与全局规划"></p><p>当前 <code>planner_server</code> 同时加载 Navfn、Smac 2D、Hybrid-A*、Lattice 和 Theta* 等插件，但自定义参数 <code>selected_planner=GridBasedAstar</code> 会固定选择 <code>nav2_navfn_planner/NavfnPlanner</code>，并设置 <code>use_astar=true</code>。</p><p>规划器的输入是当前位姿、目标位姿和 global costmap，输出是 <code>map</code> 坐标系的 <code>nav_msgs/msg/Path</code>。路径可交给 <code>smoother_server</code> 的 <code>SimpleSmoother</code> 做几何平滑，再通过行为树黑板传给 <code>FollowPath</code>。</p><p>如果规划或控制失败，行为树会调用 <code>behavior_server</code> 的 Spin、BackUp、DriveOnHeading、AssistedTeleop 或 Wait 等恢复行为，然后决定重试、重新规划或终止。</p><h2 id="六、teb-如何把路径变成速度" tabindex="-1">六、TEB 如何把路径变成速度 <a class="header-anchor" href="#六、teb-如何把路径变成速度" aria-label="Permalink to &quot;六、TEB 如何把路径变成速度&quot;">​</a></h2><p><code>controller_server</code> 接收 <code>FollowPath</code> Goal。当前 <code>bt_navigator.selected_controller=TEB</code>，因此实际调用 <code>teb_local_planner::TebLocalPlannerROS</code>。</p><p>TEB 每个控制周期主要完成：</p><h3 id="_6-1-保存并裁剪全局路径" tabindex="-1">6.1 保存并裁剪全局路径 <a class="header-anchor" href="#_6-1-保存并裁剪全局路径" aria-label="Permalink to &quot;6.1 保存并裁剪全局路径&quot;">​</a></h3><p>保存并裁剪已经走过的全局路径。</p><h3 id="_6-2-转换局部路径坐标系" tabindex="-1">6.2 转换局部路径坐标系 <a class="header-anchor" href="#_6-2-转换局部路径坐标系" aria-label="Permalink to &quot;6.2 转换局部路径坐标系&quot;">​</a></h3><p>把局部路径变换到 local costmap 的 <code>odom</code> 坐标系。</p><h3 id="_6-3-提取障碍物与-via-points" tabindex="-1">6.3 提取障碍物与 Via Points <a class="header-anchor" href="#_6-3-提取障碍物与-via-points" aria-label="Permalink to &quot;6.3 提取障碍物与 Via Points&quot;">​</a></h3><p>从 local costmap 提取障碍物，并生成路径 via points。</p><h3 id="_6-4-构建轨迹图结构" tabindex="-1">6.4 构建轨迹图结构 <a class="header-anchor" href="#_6-4-构建轨迹图结构" aria-label="Permalink to &quot;6.4 构建轨迹图结构&quot;">​</a></h3><p>用位姿顶点和时间间隔顶点表示轨迹。</p><h3 id="_6-5-执行-g2o-联合优化" tabindex="-1">6.5 执行 g2o 联合优化 <a class="header-anchor" href="#_6-5-执行-g2o-联合优化" aria-label="Permalink to &quot;6.5 执行 g2o 联合优化&quot;">​</a></h3><p>构建 g2o 图，联合优化障碍距离、速度、加速度、时间、路径长度和非完整运动学。</p><h3 id="_6-6-检查并输出速度" tabindex="-1">6.6 检查并输出速度 <a class="header-anchor" href="#_6-6-检查并输出速度" aria-label="Permalink to &quot;6.6 检查并输出速度&quot;">​</a></h3><p>检查优化发散和 footprint 碰撞，从轨迹前端计算速度指令。</p><p><img src="'+p+'" alt="TEB 控制与底盘闭环"></p><p><code>controller_server</code> 以 <code>20 Hz</code> 运行，并把内部 <code>cmd_vel</code> remap 为 <code>/cmd_vel_nav</code>。<code>velocity_smoother</code> 再以 <code>20 Hz</code> 接收该指令，按照最大速度、加速度和减速度约束平滑，输出最终 <code>/cmd_vel</code>。</p><p>bridge 把 <code>/cmd_vel</code> 转给 Ignition DiffDrive 插件，插件计算左右轮运动；仿真随后产生新的 <code>/odom</code>、TF 和 <code>/scan</code>。这些反馈再次进入定位、代价地图和控制器，闭环形成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标 -&gt; 规划 -&gt; 路径 -&gt; TEB -&gt; /cmd_vel_nav -&gt; 速度平滑 -&gt; /cmd_vel</span></span>\n<span class="line"><span>     -&gt; DiffDrive -&gt; /odom + TF + /scan -&gt; 定位/代价地图/TEB</span></span></code></pre></div><h2 id="七、生命周期和时间是两条隐形主线" tabindex="-1">七、生命周期和时间是两条隐形主线 <a class="header-anchor" href="#七、生命周期和时间是两条隐形主线" aria-label="Permalink to &quot;七、生命周期和时间是两条隐形主线&quot;">​</a></h2><p>系统能否工作，不只取决于 topic 是否存在。</p><h3 id="_7-1-生命周期" tabindex="-1">7.1 生命周期 <a class="header-anchor" href="#_7-1-生命周期" aria-label="Permalink to &quot;7.1 生命周期&quot;">​</a></h3><p>定位管理器负责 <code>map_server</code> 和 AMCL；导航管理器负责 controller、smoother、planner、behavior、bt_navigator、waypoint_follower 和 velocity_smoother。只有节点完成 configure 并进入 active，Action、publisher 和插件才真正可用。</p><h3 id="_7-2-仿真时间" tabindex="-1">7.2 仿真时间 <a class="header-anchor" href="#_7-2-仿真时间" aria-label="Permalink to &quot;7.2 仿真时间&quot;">​</a></h3><p>Ignition 发布 <code>/clock</code>，bridge 转为 ROS 2 Clock，所有配置了 <code>use_sim_time=true</code> 的节点据此计算 TF 时间、控制周期、传感器时间戳和 Action 超时。缺失 <code>/clock</code> 时，系统可能“节点都在，但数据永远对不上时间”。</p><h2 id="八、这条数据流的核心结论" tabindex="-1">八、这条数据流的核心结论 <a class="header-anchor" href="#八、这条数据流的核心结论" aria-label="Permalink to &quot;八、这条数据流的核心结论&quot;">​</a></h2><p><code>entry.launch.py</code> 的价值不在于启动节点数量，而在于建立五个边界：</p><h3 id="_8-1-ignition-与-ros-2-之间的消息边界" tabindex="-1">8.1 Ignition 与 ROS 2 之间的消息边界 <a class="header-anchor" href="#_8-1-ignition-与-ros-2-之间的消息边界" aria-label="Permalink to &quot;8.1 Ignition 与 ROS 2 之间的消息边界&quot;">​</a></h3><h3 id="_8-2-map、odom、base-footprint-之间的坐标边界" tabindex="-1">8.2 <code>map</code>、<code>odom</code>、<code>base_footprint</code> 之间的坐标边界 <a class="header-anchor" href="#_8-2-map、odom、base-footprint-之间的坐标边界" aria-label="Permalink to &quot;8.2 `map`、`odom`、`base_footprint` 之间的坐标边界&quot;">​</a></h3><h3 id="_8-3-global-costmap-与-local-costmap-之间的规划尺度边界" tabindex="-1">8.3 Global Costmap 与 Local Costmap 之间的规划尺度边界 <a class="header-anchor" href="#_8-3-global-costmap-与-local-costmap-之间的规划尺度边界" aria-label="Permalink to &quot;8.3 Global Costmap 与 Local Costmap 之间的规划尺度边界&quot;">​</a></h3><h3 id="_8-4-行为树调度与-planner-controller-插件之间的算法边界" tabindex="-1">8.4 行为树调度与 Planner／Controller 插件之间的算法边界 <a class="header-anchor" href="#_8-4-行为树调度与-planner-controller-插件之间的算法边界" aria-label="Permalink to &quot;8.4 行为树调度与 Planner／Controller 插件之间的算法边界&quot;">​</a></h3><h3 id="_8-5-cmd-vel-nav-与最终-cmd-vel-之间的速度安全边界" tabindex="-1">8.5 <code>/cmd_vel_nav</code> 与最终 <code>/cmd_vel</code> 之间的速度安全边界 <a class="header-anchor" href="#_8-5-cmd-vel-nav-与最终-cmd-vel-之间的速度安全边界" aria-label="Permalink to &quot;8.5 `/cmd_vel_nav` 与最终 `/cmd_vel` 之间的速度安全边界&quot;">​</a></h3><p>理解这五个边界后，排查 Nav2 问题就不再是“看哪个节点报错”，而是沿数据链逐段验证：时钟是否前进、TF 是否连通、传感器坐标是否正确、代价地图是否更新、规划器是否返回路径、控制器是否输出速度、bridge 是否把速度送到底盘。完整数据流，本身就是最有效的调试地图。</p>',78)])])}const q=a(h,[["render",m]]);export{f as __pageData,q as default};
